#include <cstdio>
#include <cstring>
#include <cmath>
#include <cstdlib>
#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){string s;cin>>s;int best=1,cur=1;
for(size_t i=1;i<s.size();++i){
if(s[i]==s[i-1]){++cur;best=max(best,cur);}else cur=1;}
printf("%d\n",best);return 0;}

